<template>
  <section class="course-v23" :class="{ 'course-v23--editor': view === 'editor' }">
    <template v-if="view === 'list'">
      <header class="page-head">
        <div><p class="page-kicker">COURSE MANAGEMENT</p><h1>课程内容</h1><p>管理课程内容、编辑草稿并发布至学员端。</p></div>
        <div class="page-actions"><button class="button button--secondary" type="button" @click="openBatch">批量导入</button><button class="button button--primary" type="button" @click="openCreate('lesson')">＋ 新建课程</button><button class="button button--primary" type="button" @click="openCreate('expression_skill')">＋ 新建表达技巧</button></div>
      </header>
      <div class="filter-bar">
        <label class="search-field"><span aria-hidden="true">⌕</span><input v-model.trim="search" type="search" placeholder="搜索课程名称 / 编号" aria-label="搜索课程名称或编号" /></label>
        <select v-model="kindFilter" aria-label="课程类型"><option value="all">全部类型</option><option value="lesson">课程篇</option><option value="expression_skill">表达技巧</option></select>
        <select v-model="statusFilter" aria-label="课程状态"><option value="all">全部状态</option><option value="unpublished">未发布</option><option value="enabled">已启用</option><option value="deleted">已删除</option></select>
      </div>
      <p v-if="pageError" class="notice notice--error" role="alert">{{ pageError }}</p><p v-if="pageNotice" class="notice notice--success" role="status">{{ pageNotice }}</p>
      <section class="course-table-card" aria-label="课程列表">
        <div class="course-table-head"><span>课程名称</span><span>类型</span><span>状态</span><span>更新时间</span><span>操作</span></div>
        <div v-if="loading" class="table-empty">正在读取课程…</div><div v-else-if="!filteredCourses.length" class="table-empty">没有符合条件的课程</div>
        <article v-for="item in filteredCourses" v-else :key="item.course_version_id" class="course-table-row">
          <div class="course-name"><strong>{{ item.title_zh }}</strong><span>{{ item.code || item.course_id }} · {{ item.version_label }}</span></div>
          <span class="type-label">{{ kindLabel(item.course_kind) }}</span><span><b class="status-pill" :class="`status-pill--${statusClass(item)}`"><i />{{ statusLabel(item) }}</b></span>
          <time :datetime="item.updated_at || item.published_at || ''">{{ formatDate(item.updated_at || item.published_at) }}</time>
          <div class="row-actions"><template v-if="item.course_status !== 'archived'"><button type="button" :disabled="Boolean(rowBusy)" @click="editCourse(item)">编辑</button><button type="button" :disabled="Boolean(rowBusy)" @click="openPreview(item)">预览</button><button class="row-toggle" type="button" :disabled="Boolean(rowBusy)" @click="item.has_published_version ? requestCourseAction(item.course_status === 'published' ? 'disable' : 'enable', item) : requestPublish(item)">{{ item.has_published_version ? (item.course_status === 'published' ? '停用' : '重新启用') : '发布' }}</button><button class="row-delete" type="button" :disabled="Boolean(rowBusy)" @click="requestCourseAction('delete', item)">删除</button></template><button v-else class="row-toggle" type="button" :disabled="Boolean(rowBusy)" @click="requestCourseAction('restore', item)">恢复</button></div>
        </article>
      </section><p class="list-summary">共 {{ filteredCourses.length }} 门课程</p>
    </template>

    <template v-else>
      <button class="back-link" type="button" @click="backToList">← 返回课程列表</button>
      <header class="editor-head"><div><div class="editor-title-line"><h1>{{ draft?.title_zh || form.title_zh || '新建课程' }}</h1><b class="status-pill status-pill--draft"><i />{{ isPublishedRevision ? '待发布更新' : '草稿' }}</b></div><p>{{ lastSavedText }}</p></div></header>
      <nav v-if="form.course_kind !== 'expression_skill'" class="editor-tabs" aria-label="课程编辑栏目"><button v-for="(tab, index) in editorTabs" :key="tab" type="button" :class="{ active: editorTab === index }" @click="editorTab = index">{{ tab }}</button></nav>
      <section class="editor-card">
        <template v-if="form.course_kind === 'expression_skill'">
          <SectionTitle title="表达技巧课程" text="填写基础信息并从腾讯云 COS 私有目录关联视频" />
          <div class="expression-editor">
            <div class="form-grid expression-fields">
              <label>课程名称 <em>*</em><input v-model.trim="form.title_zh" maxlength="200" placeholder="例如：微笑服务的表达技巧" /></label>
              <label>课程分类 <em>*</em><input v-model.trim="form.category" maxlength="60" placeholder="表达技巧" /></label>
              <label class="span-two">课程简介<textarea v-model.trim="form.summary" rows="4" maxlength="4000" placeholder="说明课程目标与适用场景" /></label>
              <label>排序<input v-model.number="form.sort_order" type="number" min="0" max="999999" /></label>
              <label>所属组织<select v-model="form.organization_id"><option value="">全平台公共课程</option><option v-for="item in props.organizations" :key="item.id" :value="item.id">{{ item.name }}</option></select></label>
              <label>发布范围 <em>*</em><select v-model="form.publish_scope"><option value="all_authorized">全部有权限学员</option><option value="classes">指定班级</option></select></label>
              <div v-if="form.publish_scope === 'classes'" class="class-picker"><strong>选择班级 <em>*</em></strong><label v-for="item in availableClasses" :key="item.id"><input v-model="form.publish_class_ids" type="checkbox" :value="item.id" />{{ item.name }}</label><small v-if="!availableClasses.length">当前组织暂无可用班级</small></div>
            </div>
            <aside class="cos-card">
              <header><div><b>视频资源 <em>*</em></b><span>腾讯云 COS 私有存储</span></div><i>COS</i></header>
              <div v-if="form.cos_video_key" class="cos-selected"><strong>{{ form.cos_video_filename || '已关联视频' }}</strong><small>{{ form.cos_video_key }}</small><span>{{ formatBytes(form.cos_video_size || 0) }}</span><div><button type="button" @click="previewSelectedCos">鉴权预览</button><button type="button" @click="removeCosConfirm = true">移除</button><button type="button" @click="openCosPicker">更换</button></div></div>
              <button v-else class="cos-empty" type="button" @click="openCosPicker"><b>＋</b><strong>从 COS 选择视频</strong><span>仅保存对象 Key，播放地址按权限临时生成</span></button>
              <p v-if="cosInlineError" class="notice notice--error">{{ cosInlineError }}</p>
            </aside>
          </div>
        </template>
        <template v-else-if="editorTab === 0">
          <SectionTitle title="基础设置" text="课程的名称、语言与归属" /><div class="form-grid">
            <label>课程名称 <em>*</em><input v-model.trim="form.title_zh" maxlength="200" placeholder="例如：寻找医生" /></label><label>适用语言 <em>*</em><select v-model="form.language"><option value="bilingual">中英双语</option><option value="zh">中文</option><option value="en">英文</option></select></label>
            <label>所属组织<select v-model="form.organization_id"><option value="">全平台公共课程</option><option v-for="item in props.organizations" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>分类 <em>*</em><input v-model.trim="form.category" maxlength="60" placeholder="常用广播" /></label>
          </div>
        </template>
        <template v-else-if="editorTab === 1"><SectionTitle title="封面 / 视频" text="上传课程封面；视频为可选内容" /><div class="media-grid"><MediaField title="课程封面" hint="支持 JPG、PNG、WebP，建议 16:9" accept="image/jpeg,image/png,image/webp" :file="files.cover" :existing="draft?.cover_filename || ''" @change="setMedia('cover', $event)" /><MediaField title="课程视频（可选）" hint="支持 MP4、WebM；当前音频图文课程无需上传" accept="video/mp4,video/webm" :file="files.video" :existing="draft?.video_filename || ''" @change="setMedia('video', $event)" /></div></template>
        <template v-else-if="editorTab === 2"><SectionTitle title="标准音频" text="中文、英文可分别上传最多 2 个标准音频" /><div class="media-grid media-grid--audio"><MediaField title="完整示范音频（可选）" hint="已有中英合并成品时上传" accept="audio/mpeg,audio/wav,audio/mp4,audio/aac,audio/ogg,audio/webm,audio/flac,.mp3,.wav,.m4a,.aac,.ogg,.webm,.flac" :file="files.audio" :existing="existingAudio('audio')" @change="setMedia('audio', $event)" /><MediaField v-if="form.language !== 'en'" title="中文标准音频 1" hint="支持 MP3、WAV、M4A、AAC、OGG、WebM、FLAC，最大 25 MB" accept="audio/mpeg,audio/wav,audio/mp4,audio/aac,audio/ogg,audio/webm,audio/flac,.mp3,.wav,.m4a,.aac,.ogg,.webm,.flac" :file="files.audio_zh" :existing="existingAudio('audio_zh')" @change="setMedia('audio_zh', $event)" /><MediaField v-if="form.language !== 'en'" title="中文标准音频 2" hint="可选：第二个中文版本" accept="audio/mpeg,audio/wav,audio/mp4,audio/aac,audio/ogg,audio/webm,audio/flac,.mp3,.wav,.m4a,.aac,.ogg,.webm,.flac" :file="files.audio_zh_2" :existing="existingAudio('audio_zh_2')" @change="setMedia('audio_zh_2', $event)" /><MediaField v-if="form.language !== 'zh'" title="英文标准音频 1" hint="支持 MP3、WAV、M4A、AAC、OGG、WebM、FLAC，最大 25 MB" accept="audio/mpeg,audio/wav,audio/mp4,audio/aac,audio/ogg,audio/webm,audio/flac,.mp3,.wav,.m4a,.aac,.ogg,.webm,.flac" :file="files.audio_en" :existing="existingAudio('audio_en')" @change="setMedia('audio_en', $event)" /><MediaField v-if="form.language !== 'zh'" title="英文标准音频 2" hint="可选：第二个英文版本" accept="audio/mpeg,audio/wav,audio/mp4,audio/aac,audio/ogg,audio/webm,audio/flac,.mp3,.wav,.m4a,.aac,.ogg,.webm,.flac" :file="files.audio_en_2" :existing="existingAudio('audio_en_2')" @change="setMedia('audio_en_2', $event)" /></div></template>
        <template v-else-if="editorTab === 3"><SectionTitle title="播音标注" text="设置语气、节奏、语速及中英文专业标注原文" /><div class="form-grid"><label>播音语气<input v-model="toneText" placeholder="平稳 | 解释性 | 安抚" /></label><label>语速<input v-model.trim="form.delivery_pace" placeholder="中速" /></label><label>播音节奏<input v-model="rhythmText" placeholder="清晰 | 从容" /></label><label>发音提示<input v-model.trim="form.pronunciation_notes" placeholder="专有词、连读与易错音提示" /></label><label v-if="form.language !== 'en'" class="span-two">中文专业标注原文 <em>*</em><textarea v-model="form.annotated_scripts.zh" rows="8" placeholder="短停用 /，长停用 //，升降调用 ↑ ↓。" /></label><label v-if="form.language !== 'zh'" class="span-two">英文专业标注原文 <em>*</em><textarea v-model="form.annotated_scripts.en" rows="8" placeholder="Use / for a short pause, // for a long pause, and ↑ ↓ for intonation." /></label></div></template>
        <template v-else><div class="section-title section-title--action"><div><h2>易错词</h2><p>维护课程中的重点词语、读音与常见错误</p></div><div class="mistake-actions"><button class="button button--secondary button--small" type="button" :disabled="saving" @click="downloadMistakeTemplate">下载模板</button><button class="button button--secondary button--small" type="button" :disabled="saving" @click="exportMistakeWords">导出当前易错词</button><button class="button button--secondary button--small" type="button" :disabled="saving" @click="mistakeFileInput?.click()">导入 Excel</button><button class="button button--secondary button--small" type="button" @click="addMistake">＋ 添加易错词</button><input ref="mistakeFileInput" class="hidden-file" type="file" accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" @change="selectMistakeWorkbook" /></div></div><article v-for="(word, index) in form.mistake_words" :key="index" class="mistake-card"><div class="form-grid mistake-grid"><label>语言<select v-model="word.language"><option value="zh">中文</option><option value="en">英文</option></select></label><label>词语 <em>*</em><input v-model.trim="word.term" /></label><label>读音<input v-model.trim="word.pronunciation" /></label><label>含义<input v-model.trim="word.meaning" /></label><label>常见错误<textarea v-model.trim="word.common_mistake" rows="2" /></label><label>朗读提示<textarea v-model.trim="word.tip" rows="2" /></label></div><button v-if="form.mistake_words.length > 1" class="delete-link" type="button" @click="form.mistake_words.splice(index, 1)">删除</button></article></template>
        <section class="readiness" :class="{ 'readiness--ready': readinessErrors.length === 0 }"><div class="readiness-icon">{{ readinessErrors.length ? '!' : '✓' }}</div><div><strong>发布准备度</strong><p>{{ readinessErrors.length ? `还有 ${readinessErrors.length} 项内容需要补充` : '课程内容完整，已满足发布条件' }}</p><ul v-if="readinessErrors.length"><li v-for="error in readinessErrors" :key="error">{{ error }}</li></ul></div></section>
        <p v-if="editorError" class="notice notice--error" role="alert">{{ editorError }}</p><p v-if="editorNotice" class="notice notice--success" role="status">{{ editorNotice }}</p>
      </section>
      <footer class="editor-actions"><button class="button button--secondary" type="button" :disabled="saving" @click="previewEditor">预览</button><div><button class="button button--secondary" type="button" :disabled="saving" @click="saveDraft">{{ saving ? '保存中…' : isPublishedRevision ? '仅保存草稿（不更新线上）' : '保存草稿' }}</button><button class="button button--primary" type="button" :disabled="saving" @click="publishFromEditor">{{ isPublishedRevision ? '保存并发布更新' : '发布课程' }}</button></div></footer>
    </template>
  </section>

  <div v-if="cosOpen" class="overlay" @click.self="closeCosPicker"><section class="dialog cos-dialog" role="dialog" aria-modal="true" aria-labelledby="cos-title"><header class="dialog-head"><div><span>TENCENT CLOUD COS</span><h2 id="cos-title">选择课程视频</h2><small>{{ cosBucket ? `${cosBucket} / ${cosPrefix}` : '私有课程视频目录' }}</small></div><button type="button" aria-label="关闭" @click="closeCosPicker">×</button></header><div class="dialog-body"><div class="cos-toolbar"><input v-model.trim="cosSearch" type="search" placeholder="搜索文件名或对象路径" @keyup.enter="loadCosVideos" /><button class="button button--secondary button--small" type="button" :disabled="cosLoading" @click="loadCosVideos">{{ cosLoading ? '刷新中…' : '搜索 / 刷新' }}</button></div><p v-if="cosError" class="notice notice--error">{{ cosError }} <button type="button" @click="loadCosVideos">重试</button></p><div v-else-if="cosLoading" class="table-empty">正在读取 COS 文件…</div><div v-else-if="!cosVideos.length" class="table-empty">目录中没有可用视频</div><div v-else class="cos-list"><button v-for="item in cosVideos" :key="item.key" type="button" :class="{ selected: cosSelection?.key === item.key }" @click="cosSelection = item"><span>▶</span><b>{{ item.filename }}</b><small>{{ item.key }} · {{ formatBytes(item.size) }}</small><i>{{ cosSelection?.key === item.key ? '✓' : '' }}</i></button></div></div><footer class="dialog-actions"><button class="button button--secondary" type="button" @click="closeCosPicker">取消</button><button class="button button--primary" type="button" :disabled="!cosSelection" @click="confirmCosSelection">确认关联</button></footer></section></div>
  <div v-if="cosPreviewUrl" class="overlay" @click.self="closeCosPreview"><section class="dialog preview-dialog" role="dialog" aria-modal="true"><header class="dialog-head"><div><span>AUTHENTICATED PREVIEW</span><h2>{{ form.cos_video_filename }}</h2></div><button type="button" aria-label="关闭" @click="closeCosPreview">×</button></header><div class="dialog-body"><video class="cos-preview-video" controls autoplay :src="cosPreviewUrl" @error="cosInlineError = '视频预览失败，请刷新后重试'" /></div></section></div>
  <div v-if="removeCosConfirm" class="overlay" @click.self="removeCosConfirm = false"><section class="dialog" role="alertdialog" aria-modal="true"><header class="dialog-head"><div><span>REMOVE VIDEO</span><h2>移除已关联视频？</h2></div><button type="button" @click="removeCosConfirm = false">×</button></header><div class="dialog-body"><p>只会解除课程关联，不会删除 COS 中的源文件。草稿保存后生效。</p></div><footer class="dialog-actions"><button class="button button--secondary" type="button" @click="removeCosConfirm = false">取消</button><button class="button button--primary" type="button" @click="removeCosVideo">确认移除</button></footer></section></div>

  <div v-if="previewCourse" class="overlay" @click.self="closePreview"><section class="dialog preview-dialog" role="dialog" aria-modal="true" aria-labelledby="preview-title"><header class="dialog-head"><div><span>课程预览</span><h2 id="preview-title">{{ previewCourse.title_zh }}</h2></div><button type="button" aria-label="关闭" @click="closePreview">×</button></header><div class="dialog-body"><CoursePreview :course="previewCourse" :media="previewMedia" /></div><footer class="dialog-actions"><button class="button button--secondary" type="button" @click="closePreview">关闭</button></footer></section></div>
  <div v-if="publishCandidate" class="overlay" @click.self="cancelPublish"><section class="dialog publish-dialog" role="alertdialog" aria-modal="true" aria-labelledby="publish-title"><header class="dialog-head"><div><span>COURSE PUBLISH</span><h2 id="publish-title">{{ publishCandidate.has_published_version ? '更新已发布课程' : '发布课程' }}</h2></div><button type="button" aria-label="关闭" @click="cancelPublish">×</button></header><div class="dialog-body publish-body"><p>{{ publishCandidate.has_published_version ? `确认后，《${publishCandidate.title_zh}》的新版本会替换当前线上版本，学员端刷新后即可看到。` : `发布后，《${publishCandidate.title_zh}》将进入正式课程库，并可被学习任务选择。` }}</p><div class="publish-check" :class="{ 'publish-check--error': publishCandidate.validation_errors.length }"><b>{{ publishCandidate.validation_errors.length ? '!' : '✓' }}</b><span><strong>{{ publishCandidate.validation_errors.length ? '发布校验未通过' : '发布校验已通过' }}</strong><small>{{ publishCandidate.validation_errors.length ? publishCandidate.validation_errors.join('；') : '课程内容与标准音频均已准备完成' }}</small></span></div><dl class="publish-summary"><div><dt>课程名称</dt><dd>{{ publishCandidate.title_zh }}</dd></div><div><dt>课程类型</dt><dd>{{ kindLabel(publishCandidate.course_kind) }}</dd></div><div><dt>当前状态</dt><dd>草稿</dd></div><div><dt>发布后状态</dt><dd><b class="status-pill status-pill--published"><i />已发布</b></dd></div></dl><p class="publish-note">{{ publishCandidate.has_published_version ? '新版本发布后会立即成为学员端当前版本；旧版本仍保留在历史记录中。' : '若仍有缺失项，系统会保留草稿并明确提示失败原因，不会产生半发布状态。' }}</p><p v-if="publishError" class="notice notice--error" role="alert">{{ publishError }}</p></div><footer class="dialog-actions"><button class="button button--secondary" type="button" :disabled="saving" @click="cancelPublish">取消</button><button class="button button--primary" type="button" :disabled="saving || publishCandidate.validation_errors.length > 0" @click="confirmPublish">{{ saving ? '发布中…' : publishCandidate.has_published_version ? '确认更新线上版本' : '确认发布' }}</button></footer></section></div>
  <div v-if="batchOpen" class="overlay" @click.self="closeBatch"><section class="dialog batch-dialog" role="dialog" aria-modal="true" aria-labelledby="batch-title"><header class="dialog-head"><div><span>BATCH IMPORT</span><h2 id="batch-title">批量导入课程</h2></div><button type="button" aria-label="关闭" @click="closeBatch">×</button></header><div class="dialog-body batch-body"><div class="batch-step"><strong>1. 下载并填写标准模板</strong><p>模板包含课程基础信息、课程精讲和易错词。</p><button class="button button--secondary button--small" type="button" @click="downloadTemplate">下载 Excel 模板</button></div><label class="file-line">2. 上传 Excel<input type="file" accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" @change="excelFile = pickFile($event)" /><span>{{ excelFile?.name || '选择 .xlsx 文件' }}</span></label><label class="file-line">3. 上传媒体 ZIP（可选）<input type="file" accept=".zip,application/zip" @change="zipFile = pickFile($event)" /><span>{{ zipFile?.name || '选择 .zip 文件' }}</span></label><div v-if="importResult" class="import-result"><strong>已生成 {{ importResult.created }} 个草稿，失败 {{ importResult.failed }} 个</strong><ul v-if="importResult.errors.length"><li v-for="error in importResult.errors" :key="`${error.row}-${error.course_id}-${error.message}`">第 {{ error.row || '-' }} 行 {{ error.course_id }}：{{ error.message }}</li></ul></div><p v-if="batchError" class="notice notice--error" role="alert">{{ batchError }}</p></div><footer class="dialog-actions"><button class="button button--secondary" type="button" @click="closeBatch">关闭</button><button class="button button--primary" type="button" :disabled="!excelFile || saving" @click="runImport">{{ saving ? '导入中…' : '校验并生成草稿' }}</button></footer></section></div>
  <div v-if="courseAction" class="overlay" @click.self="cancelCourseAction"><section class="dialog action-dialog" role="alertdialog" aria-modal="true" aria-labelledby="course-action-title"><header class="dialog-head"><div><span>COURSE ACTION</span><h2 id="course-action-title">{{ actionTitle(courseAction.type) }}</h2></div><button type="button" aria-label="关闭" @click="cancelCourseAction">×</button></header><div class="dialog-body"><p class="action-intro">《{{ courseAction.item.title_zh }}》</p><dl class="publish-summary"><div><dt>当前状态</dt><dd>{{ statusLabel(courseAction.item) }}</dd></div><div><dt>关联任务</dt><dd>{{ courseAction.item.task_count }} 个</dd></div><div><dt>进行中任务</dt><dd>{{ courseAction.item.active_task_count }} 个</dd></div><div><dt>对学员端的影响</dt><dd>{{ actionImpact(courseAction.type, courseAction.item) }}</dd></div></dl><p v-if="courseAction.type === 'delete' && courseAction.item.active_task_count" class="notice notice--error">存在进行中任务，必须先关闭任务后才能删除课程。</p><p v-else-if="courseAction.type === 'delete'" class="publish-note">删除采用软删除，课程版本、媒体和历史记录都会保留，可在“已删除”筛选中恢复。</p><p v-if="courseActionError" class="notice notice--error">{{ courseActionError }}</p></div><footer class="dialog-actions"><button class="button button--secondary" type="button" :disabled="Boolean(rowBusy)" @click="cancelCourseAction">取消</button><button class="button button--primary" type="button" :disabled="Boolean(rowBusy) || (courseAction.type === 'delete' && courseAction.item.active_task_count > 0)" @click="confirmCourseAction">{{ rowBusy ? '处理中…' : '确认' }}</button></footer></section></div>
  <div v-if="mistakePreview" class="overlay" @click.self="cancelMistakeImport"><section class="dialog mistake-import-dialog" role="dialog" aria-modal="true" aria-labelledby="mistake-import-title"><header class="dialog-head"><div><span>MISTAKE WORD IMPORT</span><h2 id="mistake-import-title">确认导入易错词</h2></div><button type="button" aria-label="关闭" @click="cancelMistakeImport">×</button></header><div class="dialog-body"><p class="action-intro">文件：{{ mistakeFile?.name }}</p><div class="import-counters"><div><strong>{{ mistakePreview.created }}</strong><span>新增</span></div><div><strong>{{ mistakePreview.updated }}</strong><span>更新</span></div><div><strong>{{ mistakePreview.skipped }}</strong><span>跳过</span></div><div :class="{ error: mistakePreview.invalid }"><strong>{{ mistakePreview.invalid }}</strong><span>错误</span></div></div><p class="publish-note">按“语言＋易错词”合并。确认后一次性写入当前草稿，不会留下半套数据。</p><div v-if="mistakePreview.errors.length" class="import-errors"><strong>请先修正以下问题</strong><ul><li v-for="error in mistakePreview.errors" :key="`${error.row}-${error.language}-${error.term}-${error.message}`">第 {{ error.row || '-' }} 行<span v-if="error.term">（{{ error.language }} · {{ error.term }}）</span>：{{ error.message }}</li></ul></div><p v-if="mistakeImportError" class="notice notice--error">{{ mistakeImportError }}</p></div><footer class="dialog-actions"><button class="button button--secondary" type="button" :disabled="saving" @click="cancelMistakeImport">取消</button><button class="button button--primary" type="button" :disabled="saving || mistakePreview.invalid > 0" @click="confirmMistakeImport">{{ saving ? '导入中…' : '确认并保存草稿' }}</button></footer></section></div>
</template>

<script setup lang="ts">
import { computed, defineComponent, h, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
