type CourseActionType = 'enable' | 'disable' | 'delete' | 'restore'
const editorTabs = ['基础设置', '封面 / 视频', '标准音频', '播音标注', '易错词']
const blankMistake = (): CourseMistakeWord => ({ language: 'zh', term: '', pronunciation: '', meaning: '', common_mistake: '', tip: '' })
const newCourseId = () => { const now = new Date(); const stamp = [now.getFullYear(), now.getMonth()+1, now.getDate(), now.getHours(), now.getMinutes(), now.getSeconds()].map((v,i)=>String(v).padStart(i?2:4,'0')).join(''); return `COURSE-${stamp}-${Math.random().toString(36).slice(2,6).toUpperCase()}` }
const blankForm = (): CourseV23DraftPayload => ({ course_id:newCourseId(),title_zh:'',title_en:'',category:'常用广播',summary:'',language:'bilingual',version_label:'V1.0',organization_id:null,course_kind:'lesson',content_mode:'audio_text',training_enabled:true,content_config:{training_goal:'',applicable_scenario:'',correct_demo:'',common_error_demo:''},explanation:'',annotated_scripts:{zh:'',en:''},delivery_tone:[],delivery_pace:'中速',delivery_rhythm:[],pronunciation_notes:'',mistake_words:[blankMistake()],cos_video_key:null,cos_video_filename:null,cos_video_size:null,cos_video_etag:null,sort_order:0,publish_scope:'all_authorized',publish_class_ids:[] })
const courses=ref<CourseV23Detail[]>([]),loading=ref(true),saving=ref(false),search=ref(''),kindFilter=ref<'all'|'lesson'|'expression_skill'>('all'),statusFilter=ref<'all'|'unpublished'|'enabled'|'deleted'>('all'),pageError=ref(''),pageNotice=ref(''),view=ref<'list'|'editor'>('list'),editorTab=ref(0),draft=ref<CourseV23Detail|null>(null),editorError=ref(''),editorNotice=ref(''),previewCourse=ref<CourseV23Detail|CourseV23DraftPayload|null>(null),publishCandidate=ref<CourseV23Detail|null>(null),publishError=ref(''),batchOpen=ref(false),batchError=ref(''),excelFile=ref<File|null>(null),zipFile=ref<File|null>(null),importResult=ref<CourseImportResult|null>(null)
const rowBusy=ref(''),courseAction=ref<{type:CourseActionType,item:CourseV23Detail}|null>(null),courseActionError=ref('')
const mistakeFileInput=ref<HTMLInputElement|null>(null),mistakeFile=ref<File|null>(null),mistakePreview=ref<CourseMistakeImportPreview|null>(null),mistakeImportError=ref('')
const cosOpen=ref(false),cosLoading=ref(false),cosError=ref(''),cosInlineError=ref(''),cosSearch=ref(''),cosBucket=ref(''),cosPrefix=ref(''),cosVideos=ref<CosVideoObject[]>([]),cosSelection=ref<CosVideoObject|null>(null),cosPreviewUrl=ref(''),removeCosConfirm=ref(false)
const form=reactive<CourseV23DraftPayload>(blankForm()),files=reactive<Record<MediaRole,File|null>>({cover:null,video:null,audio:null,audio_zh:null,audio_zh_2:null,audio_en:null,audio_en_2:null}),previewMedia=reactive<Partial<Record<MediaRole,string>>>({}),localUrls:string[]=[]
const splitTags=(v:string)=>v.split(/[|,，]/).map(i=>i.trim()).filter(Boolean)
const toneText=computed({get:()=>form.delivery_tone.join(' | '),set:v=>{form.delivery_tone=splitTags(v)}}),rhythmText=computed({get:()=>form.delivery_rhythm.join(' | '),set:v=>{form.delivery_rhythm=splitTags(v)}})
const lastSavedText=computed(()=>draft.value?.updated_at?`上次保存：${formatDate(draft.value.updated_at,true)}`:'尚未保存')
const availableClasses=computed(()=>props.classes.filter(item=>item.status==='active'&&(!form.organization_id||item.organization_id===form.organization_id)))
const isPublishedRevision=computed(()=>Boolean(draft.value?.status==='draft'&&draft.value?.has_published_version&&draft.value?.course_status==='published'))
const visibleVersions=computed(()=>{const groups=new Map<string,CourseV23Detail[]>();for(const item of courses.value)groups.set(item.course_id,[...(groups.get(item.course_id)||[]),item]);return [...groups.values()].map(items=>items.sort((a,b)=>{const rank=(v:CourseV23Detail)=>v.status==='draft'?3:v.status==='published'?2:1;return rank(a)!==rank(b)?rank(b)-rank(a):String(b.updated_at||b.published_at||'').localeCompare(String(a.updated_at||a.published_at||''))})[0])})
const courseState=(item:CourseV23Detail):'unpublished'|'enabled'|'deleted'=>item.course_status==='archived'?'deleted':item.course_status==='published'?'enabled':'unpublished'
const filteredCourses=computed(()=>{const needle=search.value.toLocaleLowerCase();return visibleVersions.value.filter(item=>(statusFilter.value==='deleted'||item.course_status!=='archived')&&(!needle||[item.title_zh,item.title_en,item.code,item.course_id].some(v=>String(v||'').toLocaleLowerCase().includes(needle)))&&(kindFilter.value==='all'||item.course_kind===kindFilter.value)&&(statusFilter.value==='all'||courseState(item)===statusFilter.value))})
const readinessErrors=computed(()=>validateForm(true))
function kindLabel(v:string){return v==='expression_skill'?'表达技巧':'课程篇'}
function statusLabel(item:CourseV23Detail){if(item.course_status==='archived')return'已删除';if(item.course_status!=='published')return'未发布';return item.status==='draft'?'已启用·有新草稿':'已启用'}
function statusClass(item:CourseV23Detail){return item.course_status==='archived'?'archived':item.course_status==='published'?'published':'draft'}
function formatDate(v?:string|null,withTime=false){if(!v)return'—';const d=new Date(v);if(Number.isNaN(d.getTime()))return'—';return new Intl.DateTimeFormat('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',...(withTime?{hour:'2-digit',minute:'2-digit'}:{})}).format(d)}
function setForm(source:CourseV23DraftPayload){Object.assign(form,blankForm(),{...source,organization_id:source.organization_id||'',content_config:{training_goal:'',applicable_scenario:'',correct_demo:'',common_error_demo:'',...(source.content_config||{})},annotated_scripts:{zh:'',en:'',...(source.annotated_scripts||{})},delivery_tone:[...(source.delivery_tone||[])],delivery_rhythm:[...(source.delivery_rhythm||[])],mistake_words:(source.mistake_words?.length?source.mistake_words:[blankMistake()]).map(i=>({...i})),publish_class_ids:[...(source.publish_class_ids||[])]})}
function resetFiles(){for(const role of Object.keys(files) as MediaRole[])files[role]=null}
function validateForm(forPublish=false){const e:string[]=[];if(!form.title_zh.trim())e.push('请填写课程名称');if(!form.course_id.trim())e.push('课程编号生成失败，请重新新建');if(!form.category.trim())e.push('请填写课程分类');if(form.course_kind==='expression_skill'){if(forPublish&&form.publish_scope==='classes'&&!form.publish_class_ids.length)e.push('请至少选择一个发布班级');if(forPublish&&!form.cos_video_key)e.push('请从腾讯云 COS 选择课程视频');return[...new Set(e)]}for(const lang of form.language==='bilingual'?['zh','en']:[form.language])if(!String(form.annotated_scripts[lang]||'').trim())e.push(`请填写${lang==='zh'?'中文':'英文'}专业标注原文`);if(!form.mistake_words.length||form.mistake_words.some(i=>!i.term.trim()))e.push('请至少完整填写 1 条易错词');if(forPublish){const has=(role:MediaRole)=>Boolean(files[role]||draft.value?.audio_tracks?.some(track=>track.role===role));const complete=has('audio'),zh=has('audio_zh'),en=has('audio_en');if(form.language==='bilingual'&&!complete&&!(zh&&en))e.push('双语课程需上传完整示范音频，或同时上传中文和英文标准音频 1');else if(form.language==='zh'&&!complete&&!zh)e.push('请上传中文标准音频 1');else if(form.language==='en'&&!complete&&!en)e.push('请上传英文标准音频 1')}return[...new Set(e)]}
function normalizeError(c:unknown,f:string){const x=c as {response?:{data?:{detail?:string|Array<{msg?:string}>}},message?:string};const d=x.response?.data?.detail;return typeof d==='string'?d:Array.isArray(d)?d.map(i=>i.msg).filter(Boolean).join('；')||f:x.message||f}
async function loadCourses(){loading.value=true;pageError.value='';try{courses.value=await cabinlingoApi.courseV23(true)}catch(c){pageError.value=normalizeError(c,'课程列表读取失败')}finally{loading.value=false}}
function openCreate(kind:'lesson'|'expression_skill'){draft.value=null;setForm({...blankForm(),course_kind:kind,content_mode:kind==='expression_skill'?'video':'audio_text',category:kind==='expression_skill'?'表达技巧':'常用广播'});resetFiles();editorTab.value=0;editorError.value='';editorNotice.value='';view.value='editor'}
async function editCourse(item:CourseV23Detail){pageError.value='';pageNotice.value='';try{const editable=item.status==='draft'?item:await cabinlingoApi.createCourseV23Revision(item.course_version_id);draft.value=editable;setForm(editable);resetFiles();editorTab.value=0;editorError.value='';editorNotice.value=editable.has_published_version?'当前正在编辑线上课程的新版本。点击“仅保存草稿”不会更新学员端；请点击“保存并发布更新”使修改生效。':'';view.value='editor';await loadCourses()}catch(c){pageError.value=normalizeError(c,'无法创建可编辑草稿')}}
function backToList(){view.value='list';editorError.value='';editorNotice.value='';void loadCourses()} function addMistake(){form.mistake_words.push(blankMistake())} function setMedia(role:MediaRole,file:File|null){files[role]=file} function existingAudio(role:string){return draft.value?.audio_tracks?.find(track=>track.role===role)?.filename||''}
function formatBytes(size:number){if(!size)return'大小未知';const units=['B','KB','MB','GB'];let value=size,index=0;while(value>=1024&&index<units.length-1){value/=1024;index+=1}return`${value>=10||index===0?value.toFixed(0):value.toFixed(1)} ${units[index]}`}
async function loadCosVideos(){cosLoading.value=true;cosError.value='';try{const result=await cabinlingoApi.cosVideos(cosSearch.value);cosBucket.value=result.bucket;cosPrefix.value=result.prefix;cosVideos.value=result.items}catch(c){cosVideos.value=[];cosError.value=normalizeError(c,'COS 文件列表加载失败')}finally{cosLoading.value=false}}
function openCosPicker(){cosOpen.value=true;cosSelection.value=null;cosSearch.value='';void loadCosVideos()}
function closeCosPicker(){if(!cosLoading.value)cosOpen.value=false}
function confirmCosSelection(){if(!cosSelection.value)return;const item=cosSelection.value;form.cos_video_key=item.key;form.cos_video_filename=item.filename;form.cos_video_size=item.size;form.cos_video_etag=item.etag;cosInlineError.value='';cosOpen.value=false}
async function previewSelectedCos(){if(!form.cos_video_key)return;cosInlineError.value='';try{const result=await cabinlingoApi.previewCosVideo(form.cos_video_key);cosPreviewUrl.value=result.url}catch(c){cosInlineError.value=normalizeError(c,'视频预览失败，请重试')}}
function closeCosPreview(){cosPreviewUrl.value=''}
function removeCosVideo(){form.cos_video_key=null;form.cos_video_filename=null;form.cos_video_size=null;form.cos_video_etag=null;removeCosConfirm.value=false;closeCosPreview()}
async function persistDraft(showNotice=true){editorError.value='';editorNotice.value='';const errors=validateForm(false);if(errors.length){editorError.value=errors.join('；');return null}saving.value=true;try{const payload={...form,organization_id:form.organization_id||null};const saved=draft.value?await cabinlingoApi.updateCourseV23(draft.value.course_version_id,payload,files,draft.value.updated_at):await cabinlingoApi.createCourseV23(payload,files);draft.value=saved;setForm(saved);resetFiles();if(showNotice)editorNotice.value='草稿已保存。重新进入后仍可继续编辑。';await loadCourses();emit('changed');return saved}catch(c){editorError.value=normalizeError(c,'草稿保存失败');return null}finally{saving.value=false}}
async function saveDraft(){await persistDraft(true)}
async function openPreview(item:CourseV23Detail){pageError.value='';try{const loaded=await cabinlingoApi.previewCourseV23(item.course_version_id);previewCourse.value=loaded;setRemotePreview(loaded);if(loaded.cos_video_key)previewMedia.video=(await cabinlingoApi.previewCosVideo(loaded.cos_video_key)).url}catch(c){pageError.value=normalizeError(c,'课程预览读取失败')}}
async function previewEditor(){previewCourse.value={...form,content_config:{...form.content_config},annotated_scripts:{...form.annotated_scripts},mistake_words:form.mistake_words.map(i=>({...i}))};clearPreviewUrls();for(const role of Object.keys(files) as MediaRole[]){if(files[role]){const url=URL.createObjectURL(files[role]!);localUrls.push(url);previewMedia[role]=url}else previewMedia[role]=(draft.value?.audio_tracks?.find(track=>track.role===role)?.url||draft.value?.[`${role}_url` as keyof CourseV23Detail]) as string|undefined}if(form.cos_video_key){try{previewMedia.video=(await cabinlingoApi.previewCosVideo(form.cos_video_key)).url}catch(c){editorError.value=normalizeError(c,'COS 视频预览失败')}}}
function setRemotePreview(item:CourseV23Detail){clearPreviewUrls();for(const role of Object.keys(files) as MediaRole[])previewMedia[role]=(item.audio_tracks?.find(track=>track.role===role)?.url||item[`${role}_url` as keyof CourseV23Detail]) as string|undefined} function clearPreviewUrls(){for(const url of localUrls.splice(0))URL.revokeObjectURL(url);for(const key of Object.keys(previewMedia) as MediaRole[])delete previewMedia[key]} function closePreview(){previewCourse.value=null;clearPreviewUrls()}
async function publishFromEditor(){editorError.value='';editorNotice.value='';if(readinessErrors.value.length){editorError.value=readinessErrors.value.join('；');return}const saved=await persistDraft(false);if(saved)requestPublish(saved)} function requestPublish(item:CourseV23Detail){publishError.value='';publishCandidate.value=item} function cancelPublish(){if(!saving.value){publishCandidate.value=null;publishError.value=''}}
async function confirmPublish(){if(!publishCandidate.value)return;const replacing=publishCandidate.value.has_published_version;saving.value=true;publishError.value='';try{const published=await cabinlingoApi.publishCourseV23(publishCandidate.value.course_version_id);publishCandidate.value=null;view.value='list';draft.value=null;pageNotice.value=replacing?`《${published.title_zh}》已更新发布，学员端刷新后将显示新版本。`:`《${published.title_zh}》已发布，学员端现已可见。`;await loadCourses();emit('changed')}catch(c){publishError.value=normalizeError(c,'课程发布失败')}finally{saving.value=false}}
function requestCourseAction(type:CourseActionType,item:CourseV23Detail){courseActionError.value='';courseAction.value={type,item}}
function cancelCourseAction(){if(!rowBusy.value){courseAction.value=null;courseActionError.value=''}}
function actionTitle(type:CourseActionType){return{enable:'启用课程',disable:'停用课程',delete:'删除课程',restore:'恢复课程'}[type]}
function actionImpact(type:CourseActionType,item:CourseV23Detail){if(type==='enable')return item.has_published_version?'学员课程目录将显示当前发布版本':'完成发布后学员即可看到课程';if(type==='disable')return'学员课程目录立即隐藏，历史任务仍保留';if(type==='delete')return'默认列表和学员端隐藏，历史数据保留';return'恢复为未发布状态，学员端暂不可见'}
async function confirmCourseAction(){if(!courseAction.value)return;const {type,item}=courseAction.value;if(type==='delete'&&item.active_task_count)return;if(type==='enable'&&!item.has_published_version){courseAction.value=null;requestPublish(item);return}rowBusy.value=`${type}:${item.id}`;courseActionError.value='';try{if(type==='enable')await cabinlingoApi.enableCourseV23(item.id);else if(type==='disable')await cabinlingoApi.disableCourseV23(item.id);else if(type==='delete')await cabinlingoApi.deleteCourseV23(item.id);else await cabinlingoApi.restoreCourseV23(item.id);courseAction.value=null;pageNotice.value=type==='enable'?`《${item.title_zh}》已启用，学员端现已可见。`:type==='disable'?`《${item.title_zh}》已停用，学员课程目录已隐藏。`:type==='delete'?`《${item.title_zh}》已移入已删除课程，历史数据已保留。`:`《${item.title_zh}》已恢复为未发布状态。`;await loadCourses();emit('changed')}catch(c){courseActionError.value=normalizeError(c,'课程操作失败')}finally{rowBusy.value=''}}
function downloadBlob(blob:Blob,filename:string){const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;link.click();URL.revokeObjectURL(url)}
async function downloadMistakeTemplate(){editorError.value='';try{downloadBlob(await cabinlingoApi.mistakeWordsTemplate(),'CabinLingo-易错词导入模板.xlsx')}catch(c){editorError.value=normalizeError(c,'易错词模板下载失败')}}
async function exportMistakeWords(){editorError.value='';const saved=await persistDraft(false);if(!saved)return;saving.value=true;try{downloadBlob(await cabinlingoApi.exportCourseMistakeWords(saved.course_version_id),`${saved.course_id}-易错词.xlsx`)}catch(c){editorError.value=normalizeError(c,'易错词导出失败')}finally{saving.value=false}}
async function selectMistakeWorkbook(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0]||null;input.value='';if(!file)return;mistakeImportError.value='';let saved=draft.value;if(saved)saved=await persistDraft(false);if(draft.value&&!saved)return;mistakeFile.value=file;saving.value=true;try{const existing=form.mistake_words.filter(item=>item.term.trim());mistakePreview.value=saved?await cabinlingoApi.previewCourseMistakeWordsImport(saved.course_version_id,file):await cabinlingoApi.previewNewCourseMistakeWordsImport(form.course_id,existing,file)}catch(c){editorError.value=normalizeError(c,'易错词 Excel 校验失败');mistakeFile.value=null}finally{saving.value=false}}
function cancelMistakeImport(){if(!saving.value){mistakePreview.value=null;mistakeFile.value=null;mistakeImportError.value=''}}
async function confirmMistakeImport(){if(!mistakeFile.value||!mistakePreview.value||mistakePreview.value.invalid)return;const result=mistakePreview.value;mistakeImportError.value='';if(!draft.value){form.mistake_words=result.mistake_words.map(item=>({...item}));const saved=await persistDraft(false);if(!saved){mistakeImportError.value=editorError.value||'草稿保存失败';return}draft.value=saved}else{saving.value=true;try{const saved=await cabinlingoApi.importCourseMistakeWords(draft.value.course_version_id,mistakeFile.value);draft.value=saved;setForm(saved)}catch(c){mistakeImportError.value=normalizeError(c,'易错词导入失败');return}finally{saving.value=false}}mistakePreview.value=null;mistakeFile.value=null;editorNotice.value=`易错词已保存到草稿：新增 ${result.created} 条，更新 ${result.updated} 条，跳过 ${result.skipped} 条。`;await loadCourses();emit('changed')}
function openBatch(){batchOpen.value=true;batchError.value='';excelFile.value=null;zipFile.value=null;importResult.value=null} function closeBatch(){if(!saving.value)batchOpen.value=false} function pickFile(e:Event){return(e.target as HTMLInputElement).files?.[0]||null}
async function downloadTemplate(){batchError.value='';try{const blob=await cabinlingoApi.courseV23Template();const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='CabinLingo-Course-V2.3-Template.xlsx';link.click();URL.revokeObjectURL(url)}catch(c){batchError.value=normalizeError(c,'模板下载失败')}}
async function runImport(){if(!excelFile.value)return;saving.value=true;batchError.value='';try{importResult.value=await cabinlingoApi.importCourseV23(excelFile.value,zipFile.value);await loadCourses();emit('changed')}catch(c){batchError.value=normalizeError(c,'批量导入失败')}finally{saving.value=false}}
const SectionTitle=defineComponent({props:{title:{type:String,required:true},text:{type:String,required:true}},setup:p=>()=>h('div',{class:'section-title'},[h('h2',p.title),h('p',p.text)])})
